Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -15,4 +15,30 @@
 <section class="screen menu" id="menu"><div class="menu-content"><div class="eyebrow">A living world awaits</div><h1 class="title">ETERNAL<br>WORLD</h1><div class="subtitle">Wilds of Aether</div><p class="intro">Beyond the old kingdom, the wild remembers. Find your footing, forge your legend, and discover what still stirs beneath the roots.</p><div class="menu-buttons"><button class="btn primary" id="newGame">Begin your journey <span class="arrow">↗</span></button><button class="btn" id="continueGame">Continue <span class="arrow">→</span></button><button class="btn" id="multiplayer">Enter the realm <span class="arrow">⌁</span></button><button class="btn" id="customize">Shape your wanderer <span class="arrow">✳</span></button><button class="btn" id="settings">Settings <span class="arrow">⚙</span></button></div><div class="footnote">A SOLO FRONTIER · YOUR STORY IS YOURS TO MAKE</div></div></section>
 <div class="screen hidden" id="modalRoot"></div>
 <section class="game-ui" id="gameUI"><div class="player-card"><div class="player-name" id="playerName">AEREN</div><div class="level"><span id="levelText">LEVEL 1</span> · WANDERER</div><div class="needs"><div><div class="meter-label"><span>VITALITY</span><span id="hpNum">100</span></div><div class="meter"><i id="hpBar" style="width:100%"></i></div></div><div><div class="meter-label"><span>HUNGER</span><span id="foodNum">84</span></div><div class="meter hunger"><i id="foodBar" style="width:84%"></i></div></div><div><div class="meter-label"><span>THIRST</span><span id="waterNum">76</span></div><div class="meter thirst"><i id="waterBar" style="width:76%"></i></div></div><div><div class="meter-label"><span>STAMINA</span><span id="stamNum">100</span></div><div class="meter"><i id="stamBar" style="width:100%;background:#8ac49d"></i></div></div></div></div><div class="quest"><div class="tag">✦ First light</div><strong id="questTitle">A place to begin</strong><span id="questText">Gather wood and stone<br>to make your first shelter.</span></div><div class="weather" id="weather">GOLDEN HOUR · CLEAR SKIES</div><div class="minimap"><canvas id="mapCanvas"></canvas></div><div class="biome-label" id="biomeLabel">THE GREENWARD</div><div class="bottom-left"><kbd>W A S D</kbd> move &nbsp; <kbd>E</kbd> gather / use<br><kbd>SPACE</kbd> dodge &nbsp; <kbd>I</kbd> inventory</div><div class="hotbar"><button class="slot active" data-slot="0">⚔<small>IRONBANE</small><em>1</em></button><button class="slot" data-slot="1">✦<small>EMBER</small><em>2</em></button><button class="slot" data-slot="2">◈<small>TONIC</small><em>3</em></button><button class="slot" data-slot="3">⌂<small>BUILD</small><em>4</em></button></div><div class="action-stack"><div class="action-wrap"><button class="action" id="gatherBtn">✥</button><div class="action-label">Gather</div></div><div class="action-wrap"><button class="action large" id="attackBtn">⚔</button><div class="action-label">Strike</div></div></div><div class="toast" id="toast"></div><div class="xpbar" id="xpbar" style="width:4%"></div><div class="mobile-controls"><div class="mobile-joy" id="joy"></div></div></section>
 <script>
+const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d'),mapC=document.querySelector('#mapCanvas'),mctx=mapC.getContext('2d');
+const state={screen:'menu',x:0,y:0,dx:0,dy:0,hp:100,food:84,water:76,stam:100,xp:0,level:1,wood:0,stone:0,berries:2,essence:0,day:0.28,weather:0,gender:'Wanderer',name:'Aeren',hair:0,skin:0,clothes:0,selected:0,inventory:false,inventoryTab:'Pack',quest:0,kills:0,played:false,muted:false};
+let W=innerWidth,H=innerHeight,DPR=1,now=0,last=performance.now(),toastTimer=0,attackFlash=0,particles=[],keys={},touching=false,joystick={x:0,y:0};
+const tileW=55,tileH=29,biomes=['THE GREENWARD','WHISPERING FEN','ASHEN REACH','FROSTFALL RIDGE','SUNWARD COAST','OLD KINGDOM'];
+function resize(){DPR=Math.min(devicePixelRatio||1,1.7);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);mapC.width=260;mapC.height=184}addEventListener('resize',resize);resize();
+function hash(x,y){let v=Math.sin(x*127.1+y*311.7+21.7)*43758.5453;return v-Math.floor(v)}
+function noise(x,y){let a=hash(Math.floor(x),Math.floor(y)),b=hash(Math.ceil(x),Math.floor(y)),c=hash(Math.floor(x),Math.ceil(y)),d=hash(Math.ceil(x),Math.ceil(y)),u=x-Math.floor(x),v=y-Math.floor(y);u=u*u*(3-2*u);v=v*v*(3-2*v);return (a*(1-u)+b*u)*(1-v)+(c*(1-u)+d*u)*v}
+function biomeAt(x,y){let n=noise(x*.075,y*.075);if(y>24+8*Math.sin(x*.09))return 4;if(x>32+5*Math.sin(y*.08))return 2;if(x< -27+4*Math.sin(y*.1))return 3;if(y< -30+6*Math.cos(x*.1))return 1;if(Math.abs(x-12)+Math.abs(y+18)<6)return 5;return n>.86&&Math.abs(x)<20?1:0}
+function colorTile(b,n){let colors=[['#34523c','#3d6045','#385940','#456749'],['#35584f','#3c6455','#335149','#426252'],['#776443','#876f49','#79694b','#92784c'],['#718580','#81928b','#72817e','#9aa39a'],['#49726a','#4b7f75','#49776e','#56857b'],['#5b5744','#686249','#615a46','#776b4d']][b];return colors[Math.min(3,Math.floor(n*4))]}
+function proj(x,y,z=0){return {x:W*.5+(x-y)*tileW*.5,y:H*.53+(x+y)*tileH*.5-z}}
+function drawBackground(t){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#6a8c86');sky.addColorStop(.38,'#b1aa83');sky.addColorStop(.67,'#6c795a');sky.addColorStop(1,'#243b30');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);let sunX=W*(.69+.02*Math.sin(t*.035)),sunY=H*.2;let glow=ctx.createRadialGradient(sunX,sunY,5,sunX,sunY,H*.52);glow.addColorStop(0,'rgba(255,230,167,.57)');glow.addColorStop(.18,'rgba(228,196,131,.2)');glow.addColorStop(1,'rgba(237,211,162,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H*.85);ctx.fillStyle='#ffedc2';ctx.globalAlpha=.72;ctx.beginPath();ctx.arc(sunX,sunY,22,0,7);ctx.fill();ctx.globalAlpha=1;
+// distant layered mountain silhouettes
+for(let layer=0;layer<3;layer++){let base=H*(.4+layer*.085),amp=H*(.11-layer*.017);ctx.beginPath();ctx.moveTo(0,H);ctx.lineTo(0,base);for(let x=0;x<=W+18;x+=18){let y=base-Math.abs(Math.sin(x*.004+layer*2+t*.00003)*amp)-Math.abs(Math.sin(x*.013+layer)*amp*.3);ctx.lineTo(x,y)}ctx.lineTo(W,H);ctx.closePath();ctx.fillStyle=['#7b8980','#657a65','#526d53'][layer];ctx.globalAlpha=[.6,.72,.92][layer];ctx.fill();ctx.globalAlpha=1}
+let fog=ctx.createLinearGradient(0,H*.35,0,H*.72);fog.addColorStop(0,'rgba(218,210,171,.3)');fog.addColorStop(1,'rgba(218,210,171,0)');ctx.fillStyle=fog;ctx.fillRect(0,H*.32,W,H*.42)}
+function diamond(p,color,stroke){ctx.beginPath();ctx.moveTo(p.x,p.y-tileH/2);ctx.lineTo(p.x+tileW/2,p.y);ctx.lineTo(p.x,p.y+tileH/2);ctx.lineTo(p.x-tileW/2,p.y);ctx.closePath();ctx.fillStyle=color;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.6;ctx.stroke()}}
+function tree(x,y,b,n){let p=proj(x-state.x,y-state.y);if(p.x<-50||p.x>W+50||p.y<-90||p.y>H+30)return;let s=.72+hash(x*2,y*4)*.7;if(b===3)s*=.85;ctx.fillStyle='#182a22';ctx.globalAlpha=.25;ctx.beginPath();ctx.ellipse(p.x+5,p.y+5,14*s,5*s,0,0,7);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle=b===3?'#685c4b':'#604a32';ctx.fillRect(p.x-3*s,p.y-22*s,6*s,25*s);let greens=b===1?['#27463c','#315849','#3a6652']:b===2?['#72603e','#8b7045','#9a7a4d']:b===3?['#43584c','#50665a','#63756a']:['#234a34','#2e5a3b','#3d6a43'];for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(p.x,p.y-(65-i*13)*s);ctx.lineTo(p.x-(21-i*3)*s,p.y-(31-i*12)*s);ctx.lineTo(p.x+(21-i*3)*s,p.y-(31-i*12)*s);ctx.closePath();ctx.fillStyle=greens[(i+Math.floor(n*3))%greens.length];ctx.fill();ctx.strokeStyle='#b8c17b22';ctx.lineWidth=1;ctx.stroke()}if(hash(x+39,y)<.08){ctx.fillStyle='#f0c77c';ctx.beginPath();ctx.arc(p.x+12*s,p.y-40*s,2.1,0,7);ctx.fill()}}
+function rock(x,y,n,b){let p=proj(x-state.x,y-state.y);if(p.x<-40||p.x>W+40||p.y<-50||p.y>H+50)return;let s=.55+hash(x,y+20)*.65;ctx.fillStyle='#17221c55';ctx.beginPath();ctx.ellipse(p.x,p.y+2,11*s,5*s,0,0,7);ctx.fill();ctx.beginPath();ctx.moveTo(p.x-10*s,p.y);ctx.lineTo(p.x-7*s,p.y-10*s);ctx.lineTo(p.x+1*s,p.y-16*s);ctx.lineTo(p.x+10*s,p.y-7*s);ctx.lineTo(p.x+11*s,p.y);ctx.closePath();ctx.fillStyle=b===3?'#aab0a6':b===2?'#9c8b6a':'#818b7e';ctx.fill();ctx.fillStyle='#ffffff2b';ctx.beginPath();ctx.moveTo(p.x-7*s,p.y-9*s);ctx.lineTo(p.x+1*s,p.y-15*s);ctx.lineTo(p.x+2*s,p.y-6*s);ctx.closePath();ctx.fill()}
+function drawTile(x,y,b,n){let p=proj(x-state.x,y-state.y);if(p.x<-tileW||p.x>W+tileW||p.y<-tileH||p.y>H+tileH)return;diamond(p,colorTile(b,n));if(b===4){ctx.fillStyle='rgba(28,92,95,.55)';ctx.beginPath();ctx.ellipse(p.x,p.y,8,2,0,0,7);ctx.fill()}if(b===5&&hash(x+2,y)<.15){ctx.fillStyle='#65583f';ctx.fillRect(p.x-7,p.y-7,13,7);ctx.fillStyle='#b1a178';ctx.fillRect(p.x-5,p.y-8,3,4)}if(b===1&&hash(x,y+8)<.2){ctx.strokeStyle='#8caa87';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x-1,p.y-12);ctx.moveTo(p.x,p.y-5);ctx.lineTo(p.x-6,p.y-10);ctx.stroke()}}
+function drawWater(t){for(let y=-42;y<43;y++)for(let x=-42;x<43;x++){let wx=Math.round(state.x)+x,wy=Math.round(state.y)+y,b=biomeAt(wx,wy),n=hash(wx,wy);drawTile(wx,wy,b,n);if(b===4&&n<.11)ctx.fillStyle='#d5e0bb55',ctx.fillRect(proj(wx-state.x,wy-state.y).x-2,proj(wx-state.x,wy-state.y).y-1,4,1)}}
+function drawProps(){let cx=Math.floor(state.x),cy=Math.floor(state.y);let props=[];for(let y=cy-24;y<cy+24;y++)for(let x=cx-24;x<cx+24;x++){let b=biomeAt(x,y),n=hash(x+91,y+8);if(n<.18&&b!==4&&b!==5)props.push({x,y,b,n,type:'tree'});else if(n>.7&&n<.82)props.push({x,y,b,n,type:'rock'});else if(n>.88)props.push({x,y,b,n,type:'flower'})}props.sort((a,b)=>(a.x+a.y)-(b.x+b.y));for(let o of props){if(o.type==='tree')tree(o.x,o.y,o.b,o.n);else if(o.type==='rock')rock(o.x,o.y,o.n,o.b);else{let p=proj(o.x-state.x,o.y-state.y);ctx.fillStyle=['#e8c977','#d9909e','#b7cc8b'][Math.floor(o.n*3)];ctx.beginPath();ctx.arc(p.x,p.y-4,2,0,7);ctx.fill()}}}
+function drawShelter(){let p=proj(state.x+3-state.x,state.y+1-state.y);ctx.fillStyle='#573f30';ctx.beginPath();ctx.moveTo(p.x-28,p.y);ctx.lineTo(p.x,p.y-36);ctx.lineTo(p.x+29,p.y);ctx.closePath();ctx.fill();ctx.fillStyle='#8b6541';ctx.beginPath();ctx.moveTo(p.x-29,p.y);ctx.lineTo(p.x,p.y-37);ctx.lineTo(p.x+3,p.y+1);ctx.closePath();ctx.fill();ctx.fillStyle='#27332a';ctx.fillRect(p.x-6,p.y-16,11,16)}
+function drawPlayer(t){let p=proj(0,0);let bob=Math.sin(t*.008)*2;ctx.fillStyle='#10181266';ctx.beginPath();ctx.ellipse(p.x,p.y+5,13,6,0,0,7);ctx.fill();ctx.save();ctx.translate(p.x,p.y+bob);ctx.fillStyle=['#344b45','#496447','#72543c'][state.clothes%3];ctx.beginPath();ctx.moveTo(-9,-7);ctx.lineTo(0,-29);ctx.lineTo(9,-7);ctx.lineTo(8,0);ctx.lineTo(-8,0);ctx.closePath();ctx.fill();ctx.fillStyle='#cfaa82';ctx.beginPath();ctx.arc(0,-33,6.3,0,7);ctx.fill();ctx.fillStyle=['#302a25','#573b2d','#b99258'][state.hair%3];ctx.beginPath();ctx.arc(0,-36,6.2,Math.PI,0);ctx.lineTo(6,-32);ctx.lineTo(-6,-32);ctx.closePath();ctx.fill();ctx.strokeStyle='#c8c0a3';ctx.lineWidth=2.5;ctx.beginPath();ctx.moveTo(8,-16);ctx.lineTo(14,-31);ctx.stroke();ctx.strokeStyle='#e3d8b8';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(12,-34);ctx.lineTo(16,-43);ctx.stroke();ctx.restore();if(attackFlash>0){ctx.strokeStyle=`rgba(255,218,139,${attackFlash})`;ctx.lineWidth=4;ctx.beginPath();ctx.arc(p.x,p.y-20,34,-1.3,1.5);ctx.stroke()}}
+function drawMobs(t){let spots=[];for(let y=-17;y<18;y++)for(let x=-17;x<18;x++){if(hash(x+333,y+722)<.005)spots.push({x:Math.round(state.x)+x,y:Math.round(state.y)+y})}for(let m of spots){let p=proj(m.x-state.x,m.y-state.y);let b=biomeAt(m.x,m.y);ctx.fillStyle='#17201677';ctx.beginPath();ctx.ellipse(p.x,p.y+3,10,4,0,0,7);ctx.fill();ctx.fillStyle=b===3?'#596568':b===1?'#6c8774':'#68714b';ctx.beginPath();ctx.arc(p.x,p.y-9,8,0,7);ctx.fill();ctx.fillStyle='#da7158';ctx.fillRect(p.x-4,p.y-11,2,2);ctx.fillRect(p.x+2,p.y-11,2,2)}}
+function drawParticles(){for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.y-=p.v;p.life-=.018;ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill();if(p.life<=0)particles.splice(i,1)}ctx.globalAlpha=1}
+function drawMap(){let w=mapC.width,h=mapC.height;mctx.fillStyle='#263a31';mctx.fillRect(0,0,w,h);for(let y=0;y<h;y+=4)for(let x=0;x<w;x+=4){let wx=state.x+(x-w/2)/5,wy=state.y+(y-h/2)/5,b=biomeAt(wx,wy);mctx.fillStyle=['#4b714b','#31594b','#93794d','#74857e','#488076','#655d47'][b];mctx.fillRect(x,y,4,4)}mctx.fillStyle='#f2d89b';mctx.beginPath();mctx.arc(w/2,h/2,3.5,0,7);mctx.fill()}
+function frame(t){now=t;let dt=Math.min(.05,(t-last)/1000);last=t;update(dt);drawBackground(t);drawWater(t);drawMobs(t);drawProps();if(state.played)drawShelter();drawPlayer(t);drawParticles();drawMap();requestAnimationFrame(frame)}requestAnimationFrame(frame);

input.newString:
requestAnimationFrame(frame);
function notify(msg){let el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function save(){try{localStorage.setItem('eternalWorldSave',JSON.stringify({...state,screen:undefined,inventory:undefined}))}catch(e){}}
function load(){try{let s=JSON.parse(localStorage.getItem('eternalWorldSave')||'null');if(s){Object.assign(state,s);return true}}catch(e){}return false}
function start(){state.screen='game';state.played=true;document.querySelector('#menu').classList.add('hidden');document.querySelector('#gameUI').classList.add('active');document.querySelector('#playerName').textContent=state.name.toUpperCase();showBiome(true);notify('The wilds are yours to explore.');save()}
function showBiome(force=false){let b=biomes[biomeAt(Math.round(state.x),Math.round(state.y))];let el=document.querySelector('#biomeLabel');if(force||el.dataset.biome!==b){el.textContent=b;el.dataset.biome=b;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}}
function update(dt){if(!state.played)return;let sx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joystick.x,sy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joystick.y;let len=Math.hypot(sx,sy);if(len>.1){sx/=Math.max(1,len);sy/=Math.max(1,len);let speed=state.stam>0?4.1:2.2;state.x+=sx*dt*speed;state.y+=sy*dt*speed;state.stam=Math.max(15,state.stam-dt*3);showBiome()}else state.stam=Math.min(100,state.stam+dt*13);state.day=(state.day+dt*.002)%1;state.food=Math.max(0,state.food-dt*.032);state.water=Math.max(0,state.water-dt*.052);if(state.food<1||state.water<1)state.hp=Math.max(0,state.hp-dt*1.1);if(state.hp<=0){state.hp=50;state.x=0;state.y=0;notify('You awaken at the old camp. Take better care.')}attackFlash=Math.max(0,attackFlash-dt*2.7);if(Math.random()<dt*1.2)particles.push({x:W*.5+(Math.random()-.5)*100,y:H*.53+(Math.random()-.5)*60,v:.35+Math.random(),life:.75,r:1+Math.random()*1.7,color:['#e8c981','#b5d19c','#c3d6c6'][Math.floor(Math.random()*3)]});syncHud();if(Math.random()<dt*.1)save()}
function syncHud(){for(const [id,val] of [['hp',state.hp],['food',state.food],['water',state.water],['stam',state.stam]]){document.querySelector('#'+id+'Num').textContent=Math.round(val);document.querySelector('#'+id+'Bar').style.width=Math.max(0,val)+'%'}document.querySelector('#levelText').textContent='LEVEL '+state.level;document.querySelector('#xpbar').style.width=(state.xp%100)+'%';document.querySelector('#questTitle').textContent=state.quest?'Shelter in the Wild':'A place to begin';document.querySelector('#questText').innerHTML=state.quest?`Wood ${state.wood}/5 · Stone ${state.stone}/3`:'Gather wood and stone<br>to make your first shelter.';document.querySelector('#weather').textContent=state.day<.32?'GOLDEN HOUR · CLEAR SKIES':state.day<.57?'HIGH SUN · SOFT BREEZE':state.day<.77?'DUSK · MIST RISING':'MOONLIT · COOL NIGHT'}
function gainXP(n){state.xp+=n;if(state.xp>=100){state.xp-=100;state.level++;state.hp=Math.min(100,state.hp+18);notify('Level '+state.level+' reached · A new skill awakens.')}syncHud();save()}
function gather(){let x=Math.round(state.x),y=Math.round(state.y),b=biomeAt(x,y),r=Math.random();if(b===4&&r<.28){state.water=Math.min(100,state.water+22);notify('Fresh water · Thirst restored')}else if(r<.46){state.wood+=1;notify('Gathered wildwood · '+state.wood+' in pack');gainXP(5)}else if(r<.78){state.stone+=1;notify('Gathered fieldstone · '+state.stone+' in pack');gainXP(5)}else{state.berries++;notify('Wild berries · A little food for the road');gainXP(3)}state.quest=state.wood>=5&&state.stone>=3?1:0;syncHud();save()}
function attack(){if(state.stam<9){notify('Too weary · Catch your breath');return}state.stam-=9;attackFlash=1;let r=Math.random();if(r<.6){state.kills++;state.essence++;state.hp=Math.min(100,state.hp+3);gainXP(18);notify(['Gloamling banished · +18 XP','Wild creature defeated · +18 XP','Aether shard recovered · +18 XP'][Math.floor(Math.random()*3)]);for(let i=0;i<14;i++)particles.push({x:W/2+(Math.random()-.5)*60,y:H*.53-24+(Math.random()-.5)*50,v:Math.random()*2,life:1,r:2+Math.random()*2,color:'#efbd74'})}else notify('The sword rings through the quiet woods…');save()}
function dodge(){if(state.stam<20){notify('Not enough stamina to dodge');return}state.stam-=20;state.dx=-Math.sign(keys.d-keys.a||1)*.5;state.dy=-Math.sign(keys.s-keys.w||0)*.5;state.x+=state.dx;state.y+=state.dy;attackFlash=.4;notify('Quickstep · Stamina spent')}
function useSlot(n){state.selected=n;document.querySelectorAll('.slot').forEach((el,i)=>el.classList.toggle('active',i===n));if(n===1){if(state.level<2){notify('Elemental attunement unlocks at level 2');return}state.essence=Math.max(0,state.essence-1);attackFlash=.8;gainXP(10);notify('Ember burst · Aether ripples outward')}if(n===2){if(state.berries){state.berries--;state.food=Math.min(100,state.food+25);state.hp=Math.min(100,state.hp+8);notify('Wildberry tonic · Nourishment restored')}else notify('No food in your pack yet')}if(n===3)openBuild()}
function openInventory(){if(!state.played)return;state.inventory=true;renderInventory()}
function closeModal(){document.querySelector('#modalRoot').classList.add('hidden');state.inventory=false}
function showModal(html){let root=document.querySelector('#modalRoot');root.innerHTML=html;root.classList.remove('hidden');root.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal)}
function openBuild(){showModal(`<div class="panel"><div class="panelhead"><div><div class="eyebrow">Survival · Building</div><h2>Make a camp</h2></div><button class="close" data-close>×</button></div><p class="desc">A little shelter keeps the chill at bay and gives your story a place to return to.</p><div class="recipe"><span>⌂ &nbsp; Wayfarer's lean-to<br><small>5 wildwood · 3 fieldstone</small></span><button id="buildCraft">Build · ${state.wood}/5 wood</button></div><div class="recipe"><span>◉ &nbsp; Warm berry broth<br><small>2 wild berries · restores hunger</small></span><button id="cook">Cook · ${state.berries}/2 berries</button></div><div class="panel-actions"><button class="btn" data-close>Back to the wild</button></div></div>`);document.querySelector('#buildCraft').onclick=()=>{if(state.wood>=5&&state.stone>=3){state.wood-=5;state.stone-=3;state.quest=1;state.played=true;gainXP(25);closeModal();notify('A shelter takes shape beside the trail.')}else notify('Gather 5 wood and 3 stone first.')};document.querySelector('#cook').onclick=()=>{if(state.berries>=2){state.berries-=2;state.food=Math.min(100,state.food+40);gainXP(8);notify('Warm broth · Hunger restored')}else notify('Gather 2 wild berries first.')};}
function renderInventory(){showModal(`<div class="panel"><div class="panelhead"><div><div class="eyebrow">Wanderer's satchel</div><h2>Inventory & craft</h2></div><button class="close" data-close>×</button></div><p class="desc">Your kit is light. The wilds will provide the rest.</p><div class="inventory-grid"><div class="invslot"><b>⚔</b>Ironbane<br><span>Equipped</span></div><div class="invslot"><b>🛡</b>Leather vest<br><span>Armor · 4</span></div><div class="invslot"><b>✧</b>Aether shard<br><span>${state.essence}</span></div><div class="invslot"><b>◉</b>Wild berries<br><span>${state.berries}</span></div><div class="invslot"><b>⌁</b>Wildwood<br><span>${state.wood}</span></div><div class="invslot"><b>⬡</b>Fieldstone<br><span>${state.stone}</span></div><div class="invslot"><b>◌</b>Level ${state.level}<br><span>${state.xp} / 100 XP</span></div><div class="invslot"><b>✦</b>Ember affinity<br><span>${state.level>=2?'Awakened':'Locked · Lv. 2'}</span></div></div><div class="field"><label>Quick recipes</label><div class="recipe"><span>⌂ &nbsp; Wayfarer's lean-to<br><small>5 wildwood · 3 fieldstone</small></span><button id="invBuild">Craft</button></div><div class="recipe"><span>◉ &nbsp; Berry tonic<br><small>2 berries · restores hunger</small></span><button id="invFood">Use</button></div></div><div class="panel-actions"><button class="btn" data-close>Return to the wild</button></div></div>`);document.querySelector('#invBuild').onclick=()=>{closeModal();openBuild()};document.querySelector('#invFood').onclick=()=>useSlot(2)}

